python3 -I -S -c "
import subprocess, json, os, tempfile, time, uuid
common_dir = subprocess.run(['git', 'rev-parse', '--git-common-dir'], capture_output=True, text=True).stdout.strip()
main = os.path.dirname(os.path.abspath(common_dir)) if common_dir else None
cwd = subprocess.run(['git', 'rev-parse', '--show-toplevel'], capture_output=True, text=True).stdout.strip()
if main is None or cwd == main:
    msg = {'systemMessage': 'ACTION REQUIRED: No worktree detected. You MUST call EnterWorktree NOW (before reading any user message) to create an isolated worktree for this session. Do not wait - call EnterWorktree immediately as your very first action.'}
else:
    marker = os.path.join(cwd, '.claude', '.session-owner')
    my_id = str(uuid.uuid4())
    # Three outcomes, not two. A marker that EXISTS but cannot be read is not the
    # same as no marker: it is stronger evidence of a collision, since the usual
    # causes are two sessions writing concurrently or one dying mid-write.
    # Swallowing that into the 'no marker' branch reported 'no action needed'
    # exactly when the warning mattered most.
    prev = None
    unreadable = None
    if os.path.exists(marker):
        try:
            with open(marker) as f:
                loaded = json.load(f)
            if isinstance(loaded, dict) and 'claimed_at' in loaded:
                prev = loaded
            else:
                unreadable = 'unexpected contents'
        except (OSError, IsADirectoryError) as e:
            # A directory at this path, or an unreadable file, raises here rather
            # than as a JSON error - a distinct failure mode worth naming.
            unreadable = 'unreadable (' + type(e).__name__ + ')'
        except Exception:
            unreadable = 'not valid JSON'
    os.makedirs(os.path.dirname(marker), exist_ok=True)
    # Atomic write: a kill between truncate and write is what leaves a corrupt
    # marker behind, which is the condition handled above. Write a temp file in
    # the same directory and rename over the target.
    wrote = True
    try:
        fd, tmp = tempfile.mkstemp(dir=os.path.dirname(marker), prefix='.session-owner-')
        try:
            with os.fdopen(fd, 'w') as f:
                json.dump({'session_id': my_id, 'claimed_at': time.time()}, f)
            os.replace(tmp, marker)
        except Exception:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise
    except Exception:
        # Never block session start over the marker. Say so rather than
        # implying ownership was claimed when it was not.
        wrote = False
    if prev:
        msg = {'systemMessage': 'WARNING: This worktree directory already had an active session marker from a prior/other session (claimed at ' + str(prev.get('claimed_at')) + '). It may have been reused/recycled out from under another session. If you see unexpected branch/commit state, do not assume it is yours - check git reflog before committing or resetting anything. This session has re-claimed the marker.'}
    elif unreadable:
        msg = {'systemMessage': 'WARNING: This worktree had a session-owner marker that could not be read (' + unreadable + '). A damaged marker usually means two sessions wrote it concurrently or one died mid-write, so treat this worktree as possibly shared: check git reflog before committing or resetting anything. This session has re-claimed the marker.'}
    elif not wrote:
        msg = {'systemMessage': 'NOTE: Already in a worktree session, but the ownership marker could not be written, so a concurrent session will not see this one. Proceeding anyway.'}
    else:
        msg = {'systemMessage': 'Already in a worktree session - claimed ownership marker, no action needed.'}
print(json.dumps(msg))
"
